import hashlib, random, time

def idem_key(parent_run_id: str, step_id: str) -> str:
    return hashlib.sha256(f"{parent_run_id}:{step_id}".encode()).hexdigest()[:32]

def delegate(client, run_id: str, step_id: str, payload: dict, deadline_s: int = 600) -> dict:
    key = idem_key(run_id, step_id)
    task = client.submit(payload, idempotency_key=key)  # 子 Agent 侧唯一索引，重复提交返回同一 task
    end, backoff = time.time() + deadline_s, 1.0
    while time.time() < end:
        st = client.get_task(task.task_id)  # 只读状态接口，不进执行队列
        if st.state in ("succeeded", "failed", "cancelled"):
            return {"state": st.state, "result": st.result, "key": key}
        time.sleep(backoff + random.random() * 0.2)
        backoff = min(backoff * 2, 30.0)
    return {"state": "unknown", "task_id": task.task_id, "key": key}

def run_side_effect(store, run_id: str, step, execute, probe=None):
    key = idem_key(run_id, step.id)
    if (out := store.get_outcome(key)) is not None:
        return out
    store.put_intent(key, step.digest)          # 先落意图，再执行
    if store.get_intent(key) and probe and probe():   # 已执行但结果丢失，走对账
        return store.get_outcome(key)
    out = execute()
    store.put_outcome(key, out)
    return out

RETRYABLE_CODES = {-32603, -32001}

def call_tool(client, name, args, max_attempts=3):
    fp = fingerprint(name, args)
    for attempt in range(1, max_attempts + 1):
        try:
            res = client.call("tools/call", {"name": name, "arguments": args})
        except JsonRpcError as e:
            if e.code == -32602 or breaker.hit(fp):
                raise ToolFatal(name, e.code, e.message)      # 参数错 或 已熔断 不重试
            if e.code in RETRYABLE_CODES and attempt < max_attempts:
                time.sleep(min(2 ** attempt, 10) * (0.5 + random.random()))
                continue
            raise ToolFatal(name, e.code, e.message)
        if res.get("isError"):
            payload = json.loads(res["content"][0]["text"])
            if payload.get("retryable") and attempt < max_attempts:
                time.sleep(min(2 ** attempt, 10)); continue
            breaker.record(fp)
            raise ToolBusinessError(payload["code"], payload.get("hint"))
        return res

def handle_tools_call(req):
    tool = registry.get(req.params["name"])
    if tool is None:
        return error(req.id, -32601, "unknown tool")
    if (fields := tool.schema.check(req.params.get("arguments", {}))):
        return error(req.id, -32602, "invalid params", data={"fields": fields})
    try:
        out = tool.run(req.params["arguments"])
    except ToolBusinessError as e:
        return result(req.id, {"isError": True, "content": [{"type": "text", "text": json.dumps(
            {"code": e.code, "retryable": e.retryable, "hint": e.hint})}]})
    except Exception:
        return error(req.id, -32603, "internal error", data={"trace_id": current_trace()})
    return result(req.id, {"isError": False, "content": out})

from dataclasses import dataclass

@dataclass
class Verdict:
    passed: bool
    code: str
    fix_hint: str = ""

def validate(task, draft, budget):
    for chk in HARD_CHECKS:                 # schema / 引用 / 合规，不花钱
        v = chk(draft)
        if not v.passed:
            return v
    if not risky(task):                     # 低风险直接放行
        return Verdict(True, "skipped")
    if budget.exhausted():
        return Verdict(True, "budget_exhausted")
    return llm_judge(task, draft, rubric=RUBRIC)

def run(task, budget):
    draft, v, prev = generate(task), None, None
    for _ in range(max_rounds(task)):
        v = validate(task, draft, budget)
        if v.passed or v.code == "budget_exhausted":
            break
        if prev is not None and jaccard(prev, draft) > 0.9:
            return draft, "needs_human", v      # 重写震荡，止损
        prev = draft
        draft = rewrite(task, draft, v.fix_hint, budget)
    return draft, "ok", v

UNSET = object()

def resolve(defaults, profile, request):
    out = dict(defaults)
    for layer in (profile, request):
        for k, v in layer.items():
            if v is UNSET:
                continue
            out[k] = v          # False / 0 是合法值，不能被 or 吞掉
    return out

