from pydantic import BaseModel

class ModelArgs(BaseModel):
    think: bool | None = None
    temperature: float | None = None

def to_payload(args: ModelArgs, defaults: dict) -> dict:
    explicit = args.model_dump(exclude_unset=True)   # 区分「没传」与「传了 False」
    return {**defaults, **{k: v for k, v in explicit.items() if v is not None}}

import numpy as np

def recall_at_k(ref_ids, got_ids, k=10):
    return len(set(ref_ids[:k]) & set(got_ids[:k])) / k

def compare_configs(store, queries, k=10, oversample=4):
    rows = []
    for q in queries:
        ref = store.search(q, limit=k, exact=True)
        sq = store.search(q, limit=k, quant="sq8", rescore=False)
        sq_r = store.search(q, limit=k, quant="sq8",
                            oversample=oversample, rescore=True)
        rows.append([recall_at_k(ref, sq, k), recall_at_k(ref, sq_r, k)])
    mean = np.mean(rows, axis=0)
    return {"sq8": round(float(mean[0]), 4),
            "sq8_rescore": round(float(mean[1]), 4)}

import asyncio, hashlib

class BatchedEmbedder:
    def __init__(self, embed_fn, cache, max_batch=64, max_delay=0.01, workers=2):
        self.embed_fn, self.cache = embed_fn, cache
        self.max_batch, self.max_delay = max_batch, max_delay
        self.q, self.sem = asyncio.Queue(), asyncio.Semaphore(workers)

    async def embed(self, text):
        key = hashlib.sha256(text.encode()).hexdigest()
        if (hit := self.cache.get(key)) is not None:
            return hit
        fut = asyncio.get_running_loop().create_future()
        await self.q.put((text, key, fut))
        return await asyncio.wait_for(fut, timeout=2.0)

    async def run(self):
        loop = asyncio.get_running_loop()
        while True:
            batch = [await self.q.get()]
            deadline = loop.time() + self.max_delay
            while len(batch) < self.max_batch:
                left = deadline - loop.time()
                if left <= 0:
                    break
                try:
                    batch.append(await asyncio.wait_for(self.q.get(), left))
                except asyncio.TimeoutError:
                    break
            async with self.sem:
                try:
                    vecs = await self.embed_fn([t for t, _, _ in batch])
                    for (_, k, fut), v in zip(batch, vecs):
                        self.cache[k] = v
                        fut.set_result(v)
                except Exception as e:
                    for _, _, fut in batch:
                        if not fut.done():
                            fut.set_exception(e)

def gate(query, chunks, reranker, coverage_fn, cfg):
    scored = sorted(
        ((reranker.score(query, c.text), c) for c in chunks),
        key=lambda x: x[0], reverse=True,
    )[: cfg.top_n]
    if not scored:
        return {"action": "refuse", "reason": "empty_recall"}

    top_score = scored[0][0]
    cov = coverage_fn(query, [c for _, c in scored])
    base = cfg.thresholds.get(classify(query), cfg.thresholds["default"])

    if top_score < base or cov < cfg.min_coverage:
        return {
            "action": "retry_or_refuse",
            "top_score": top_score,
            "coverage": cov,
            "rewrite": True,
        }
    return {
        "action": "answer",
        "context": [c for _, c in scored],
        "top_score": top_score,
        "coverage": cov,
    }

